int push(Vec*v,int x){if(v->len==v->cap){size_t c=v->cap?v->cap*2:8;if(c<v->cap||c>SIZE_MAX/sizeof(int))return 0;int*t=realloc(v->data,c*sizeof(int));if(!t)return 0;v->data=t;v->cap=c;}v->data[v->len++]=x;return 1;}
