#include "log.h"
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
static char*dup_text(const char*s,size_t n){if(n>SIZE_MAX-1)return NULL;char*p=malloc(n+1);if(!p)return NULL;memcpy(p,s,n);p[n]=0;return p;}
void log_store_init(LogStore*s){if(s){s->items=NULL;s->len=s->cap=0;}}
void log_record_destroy(LogRecord*r){if(r){free(r->timestamp);free(r->message);r->timestamp=r->message=NULL;}}
void log_store_destroy(LogStore*s){if(!s)return;for(size_t i=0;i<s->len;i++)log_record_destroy(&s->items[i]);free(s->items);log_store_init(s);}
static int level(const char*s,LogLevel*out){if(strcmp(s,"INFO")==0)*out=LOG_INFO;else if(strcmp(s,"WARN")==0)*out=LOG_WARN;else if(strcmp(s,"ERROR")==0)*out=LOG_ERROR;else return 0;return 1;}
int log_parse_line(const char*line,LogRecord*out){if(!line||!out)return 0;out->timestamp=out->message=NULL;const char*a=strchr(line,'|');if(!a)return 0;const char*b=strchr(a+1,'|');if(!b||a==line||b==a+1)return 0;const char*e=strchr(b+1,'\n');size_t mn=e?(size_t)(e-b-1):strlen(b+1);if(!mn)return 0;char*ls=dup_text(a+1,(size_t)(b-a-1));if(!ls)return 0;LogLevel lv;if(!level(ls,&lv)){free(ls);return 0;}free(ls);char*ts=dup_text(line,(size_t)(a-line));char*msg=dup_text(b+1,mn);if(!ts||!msg){free(ts);free(msg);return 0;}out->timestamp=ts;out->message=msg;return (out->level=lv),1;}
int log_store_push(LogStore*s,LogRecord*r){if(!s||!r)return 0;if(s->len==s->cap){size_t c=s->cap?s->cap*2:8;if(c<s->cap||c>SIZE_MAX/sizeof(*s->items))return 0;LogRecord*t=realloc(s->items,c*sizeof(*s->items));if(!t)return 0;s->items=t;s->cap=c;}s->items[s->len++]=*r;r->timestamp=r->message=NULL;return 1;}
size_t log_count_level(const LogStore*s,LogLevel lv){size_t n=0;if(!s)return 0;for(size_t i=0;i<s->len;i++)if(s->items[i].level==lv)n++;return n;}

