#include "log.h"
#include <stdio.h>
#include <string.h>
int main(int argc,char**argv){if(argc!=2){fprintf(stderr,"usage: %s FILE
",argv[0]);return 2;}FILE*f=fopen(argv[1],"r");if(!f){perror(argv[1]);return 1;}LogStore s;log_store_init(&s);char line[4096];size_t no=0;int rc=0;while(fgets(line,sizeof line,f)){no++;size_t n=strlen(line);if(n==sizeof line-1&&line[n-1]!='
'&&!feof(f)){fprintf(stderr,"line %zu too long
",no);rc=1;break;}LogRecord r;if(!log_parse_line(line,&r)){fprintf(stderr,"invalid line %zu
",no);rc=1;break;}if(!log_store_push(&s,&r)){log_record_destroy(&r);rc=1;break;}}if(ferror(f))rc=1;fclose(f);if(!rc)printf("records=%zu info=%zu warn=%zu error=%zu
",s.len,log_count_level(&s,LOG_INFO),log_count_level(&s,LOG_WARN),log_count_level(&s,LOG_ERROR));log_store_destroy(&s);return rc;}
